def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    bits = int(state, 2)
    mask = (1 << n) - 1

    shifts = set()
    for offset in offsets:
        d = offset % n
        if d in shifts:
            shifts.remove(d)
        else:
            shifts.add(d)

    while t:
        if t & 1:
            next_bits = 0
            for d in shifts:
                next_bits ^= ((bits << d) & mask) | (bits >> (n - d))
            bits = next_bits

        t >>= 1
        if t:
            next_shifts = set()
            for d in shifts:
                doubled = (2 * d) % n
                if doubled in next_shifts:
                    next_shifts.remove(doubled)
                else:
                    next_shifts.add(doubled)
            shifts = next_shifts

    return format(bits, f"0{n}b")
